139: void ataxGpu(DATA_TYPE* A, DATA_TYPE* x, DATA_TYPE* y, DATA_TYPE* tmp, DATA_TYPE* y_outputFromGpu)
140: {
141: 	double t_start, t_end;
142: 
143: 	DATA_TYPE *A_gpu;
144: 	DATA_TYPE *x_gpu;
145: 	DATA_TYPE *y_gpu;
146: 	DATA_TYPE *tmp_gpu;
147: 
148: 	cudaMalloc((void **)&A_gpu, sizeof(DATA_TYPE) * NX * NY);
149: 	cudaMalloc((void **)&x_gpu, sizeof(DATA_TYPE) * NY);
150: 	cudaMalloc((void **)&y_gpu, sizeof(DATA_TYPE) * NY);
151: 	cudaMalloc((void **)&tmp_gpu, sizeof(DATA_TYPE) * NX);
152: 	
153: 	cudaMemcpy(A_gpu, A, sizeof(DATA_TYPE) * NX * NY, cudaMemcpyHostToDevice);
154: 	cudaMemcpy(x_gpu, x, sizeof(DATA_TYPE) * NY, cudaMemcpyHostToDevice);
155: 	cudaMemcpy(y_gpu, y, sizeof(DATA_TYPE) * NY, cudaMemcpyHostToDevice);
156: 	cudaMemcpy(tmp_gpu, tmp, sizeof(DATA_TYPE) * NX, cudaMemcpyHostToDevice);
157: 	
158: 	dim3 block(DIM_THREAD_BLOCK_X, DIM_THREAD_BLOCK_Y);
159: 	dim3 grid1((size_t)(ceil( ((float)NX) / ((float)block.x) )), 1);
160: 	dim3 grid2((size_t)(ceil( ((float)NY) / ((float)block.x) )), 1);
161: 
162: 	t_start = rtclock();
163: 	atax_kernel1<<< grid1, block >>>(A_gpu,x_gpu,tmp_gpu);
164: 	cudaThreadSynchronize();
165: 	atax_kernel2<<< grid2, block >>>(A_gpu,y_gpu,tmp_gpu);
166: 	cudaThreadSynchronize();
167: 	t_end = rtclock();
168: 	fprintf(stdout, "GPU Runtime: %0.6lfs\n", t_end - t_start);
169: 	
170: 	cudaMemcpy(y_outputFromGpu, y_gpu, sizeof(DATA_TYPE) * NX, cudaMemcpyDeviceToHost);
171: 
172: 	cudaFree(A_gpu);
173: 	cudaFree(x_gpu);
174: 	cudaFree(y_gpu);
175: 	cudaFree(tmp_gpu);
176: }
